        mem[wr_ptr_next] <= din;
        wr_ptr <= wr_ptr + 1;
      end
      if (rd_en && !empty) begin
        rd_ptr <= rd_ptr + 1;
      end
    end
  end

  always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
      dout <= 0;
    end else begin
      if (rd_en && !empty) begin
        dout <= mem[rd_ptr_next];
