  always @(posedge wclk or negedge wrst_n) begin
    if (!wrst_n) begin
      wptr_bin <= 0;
      wptr_gray <= 0;
    end else begin
      wptr_bin <= wptr_bin_next;
      wptr_gray <= wptr_gray_next;
    end
  end

  // Calculate next write pointer
  always @(*) begin
    if (winc && !wfull) begin
      wptr_bin_next = wptr_bin + 1;
      wptr_gray_next = wptr_bin_next ^ (wptr_bin_next >> 1);
    end else begin
      wptr_bin_next = wptr_bin;
      wptr_gray_next = wptr_gray;
